import{_ as o,o as t,c as d,a5 as c}from"./chunks/framework.DSg0KOwT.js";const p=JSON.parse('{"title":"Plan Advisor","description":"","frontmatter":{},"headers":[],"relativePath":"contributor-guide/architecture/board-widgets/plan-advisor.md","filePath":"contributor-guide/architecture/board-widgets/plan-advisor.md"}'),a={name:"contributor-guide/architecture/board-widgets/plan-advisor.md"};function n(i,e,r,s,l,h){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="plan-advisor" tabindex="-1">Plan Advisor <a class="header-anchor" href="#plan-advisor" aria-label="Permalink to &quot;Plan Advisor&quot;">​</a></h1><p>The Plan Advisor board widgets, which report SQL-plan-level findings.</p><ul><li><strong>Plan Advisor</strong> (tag <code>PLAN</code>): SQL-plan-level findings computed from <code>appModel.sql</code>&#39;s resolved <code>planTree</code> (DETECTORS entries <code>duplicatePlanSubtree</code>, <code>smallFiles</code>, <code>nestedLoopJoin</code>, <code>joinKeyCast</code>, <code>mergeRewrite</code>, <code>unprunedScan</code>, <code>broadcastSizing</code>, <code>pythonUdf</code> in <code>packages/core/src/detectors.ts</code>): repeated plan subtrees (≥3 nodes, ≥2 occurrences; dropped when their linked stages take under 0.5% of the run; banded from the recovered wall-clock like other findings, with a <code>warning</code>/<code>info</code> fallback; an <code>Exchange</code> root only changes the recommendation to a possible missed exchange reuse), small-files read/write (&gt;100 files averaging ❤️ MiB), nested-loop and cartesian joins whose output dwarfs their inputs (<code>nestedLoopJoin</code>, graded by the time of the stages that run the join), shuffled joins whose key carries a cast, so that an exchange after the join shuffles by the uncast column again (<code>joinKeyCast</code>, an info finding; its <code>value</code> is that exchange&#39;s <code>data size</code>), Delta MERGEs that rewrite mostly unmodified rows or keep most target files after skipping (<code>mergeRewrite</code>, two rules, each an info finding; <code>target</code> is read with <code>resolveDeltaCommandTarget</code>, so it is null when the log names no single target), filtered scans of a partitioned table with no partition filter (<code>unprunedScan</code>, a low-confidence info finding: the plan does not name the partition columns), and broadcast-join sizing in both directions (missed- broadcast info finding, over-broadcast warning at &gt;1 GB), and row-at-a-time Python UDFs (<code>BatchEvalPython</code> stages that sent &gt;64 MiB to Python workers over &gt;30 s; an info finding). Each of the nine emitted types renders as its own card (<code>DuplicatePlanSubtree.tsx</code>, <code>SmallFiles.tsx</code>, <code>NestedLoopJoin.tsx</code>, <code>JoinKeyCast.tsx</code>, <code>MergeRewrite.tsx</code>, <code>UnprunedScan.tsx</code>, <code>UnderBroadcast.tsx</code>, <code>OverBroadcast.tsx</code>, <code>PythonUdf.tsx</code>): all nine share the <code>PLAN</code> tag and the same <code>--plan-aggregate</code> badge tint (<code>src/view/plan-finding-shared.ts</code>). Their <code>docAnchor</code>s (<code>#bottleneck-duplicate-plan-subtree</code>, <code>#bottleneck-small-files</code>, <code>#bottleneck-broadcast-sizing</code>, <code>#pyspark</code>) each resolve to their own page in the vendored tuning reference; <code>nestedLoopJoin</code> and <code>joinKeyCast</code> link to the reference&#39;s <code>#joins</code> chapter and <code>mergeRewrite</code> and <code>unprunedScan</code> to its <code>#table-formats</code> chapter.</li></ul><p><code>detector-registry.tsx</code>&#39;s <code>REGISTRY</code> carries <code>region: &#39;reference&#39;</code> on four entries, each its own component: <code>memoryUtilization</code> (<code>MemoryUtilization</code>), <code>utilization</code> (<code>ExecutorUtilization</code>), <code>cacheUtilization</code> (<code>CacheUtilization</code>), and <code>coreLocality</code> (<code>CoreUsageArea</code>). <code>broadcastSizing</code> has no <code>REGISTRY</code> entry: it never backs a real <code>Finding</code> (the <code>broadcastSizing</code> <code>DETECTORS</code> entry only emits <code>underBroadcast</code>/<code>overBroadcast</code>, both <code>region: &#39;action&#39;</code>, each its own Plan Advisor card), so there is no key for it to occupy or clean-check line for it to render. Autoscaling Churn, the other executor-provisioning-lifecycle detector alongside <code>utilization</code>/<code>memoryUtilization</code>, is <code>action</code>, not <code>reference</code> (see &quot;App- and plan-level widgets&quot; above).</p><p><code>region</code> decides one thing (see <a href="./../widget-rendering.html#widget-rendering-order">Widget rendering order</a>): whether a widget always mounts. <code>isAlwaysMountedType()</code> flags exactly one of the four <code>reference</code>-region types: Core Usage by Locality. That one mounts unconditionally from <code>appModel</code> at the head of the Full app report tab&#39;s reference grid, regardless of finding state. Memory Utilization, Executor Utilization, and Cache Storage are <code>reference</code> too, but all three are excluded by product decision, not a component-sharing constraint (<code>ALWAYS_MOUNTED_EXCEPTIONS</code> in <code>src/view/detector-registry.tsx</code> carries <code>cacheUtilization</code>, <code>memoryUtilization</code>, and <code>utilization</code>): a clean run on any of them isn&#39;t evidence worth surfacing unconditionally, so each collapses to an ordinary <code>CleanCheckRow</code> like any other action-region type on a clean run. Every other <code>REGISTRY</code> widget renders unconditionally as either an active card or a clean-check line, and <code>region</code>, then detector order, breaks ties between cards of the same impact band (<code>computeActiveWidgets</code> ranks by worst impact band first; <code>ImpactBoard</code> groups cards Critical, Warning, Info). The Full app report tab reads no other <code>REGISTRY</code> entry. So Core Usage by Locality, the one widget tagged <code>region: &#39;reference&#39;</code> and exempt from <code>ALWAYS_MOUNTED_EXCEPTIONS</code>, renders in the Full app report beside the other run-wide reference views, and a route to a <code>coreLocality</code> finding switches to that tab (Memory Utilization, Executor Utilization, and Cache Storage all render through the ordinary active/clean paths instead):</p>',5)])])}const u=o(a,[["render",n]]);export{p as __pageData,u as default};
